draw:
var r = p.radius, v = p.speed, m = p.mass;
var a = v * v / r;
var T = 2 * Math.PI * r / v;
var om = v / r;
var F = m * a;

var cx = W * 0.42, cy = H * 0.52;
var R = Math.min(W * 0.26, H * 0.34);
var ang = (v / r) * t;

ctx.lineWidth = 1;
ctx.strokeStyle = C.rule;
ctx.setLineDash([4, 5]);
ctx.beginPath(); ctx.arc(cx, cy, R, 0, Math.PI * 2); ctx.stroke();
ctx.setLineDash([]);

var bx = cx + R * Math.cos(ang), by = cy + R * Math.sin(ang);

// radius line
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(bx, by); ctx.stroke();

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

function arrow(x0, y0, x1, y1, col) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
  var th = Math.atan2(y1 - y0, x1 - x0);
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 8 * Math.cos(th - 0.4), y1 - 8 * Math.sin(th - 0.4));
  ctx.lineTo(x1 - 8 * Math.cos(th + 0.4), y1 - 8 * Math.sin(th + 0.4));
  ctx.closePath(); ctx.fill();
  ctx.lineWidth = 1;
}

// velocity: tangent, length fixed-ish scaled by speed
var vlen = R * 0.35 * (v / 12) + R * 0.25;
var tx = -Math.sin(ang), ty = Math.cos(ang);
arrow(bx, by, bx + tx * vlen, by + ty * vlen, C.figure);
ctx.fillStyle = C.figure;
ctx.fillText("v", bx + tx * vlen + 6, by + ty * vlen + 4);

// acceleration: inward
var alen = R * 0.55 * Math.min(1, a / 120) + R * 0.18;
arrow(bx, by, bx - Math.cos(ang) * alen, by - Math.sin(ang) * alen, C.accent);
ctx.fillStyle = C.accent;
ctx.fillText("a = v^2/r", bx - Math.cos(ang) * alen - 30, by - Math.sin(ang) * alen - 8);

// ball and centre
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(bx, by, 6, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(cx, cy, 3, 0, Math.PI * 2); ctx.fill();
ctx.fillText("r = " + r.toFixed(1) + " m", cx + 6, cy - 8);

// speed trace: the speed never changes, show a bar
var px = W * 0.78;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(px, H * 0.18); ctx.lineTo(px, H * 0.82); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillRect(px + 4, H * 0.82 - (H * 0.64) * (v / 12), 16, (H * 0.64) * (v / 12));
ctx.fillStyle = C.ink;
ctx.fillText("speed", px - 4, H * 0.14);
ctx.fillText(v.toFixed(1) + " m/s", px - 4, H * 0.9);

out.note = "a = " + a.toFixed(2) + " m/s^2,  F = m a = " + F.toFixed(2) + " N,  period T = " + T.toFixed(2) + " s,  omega = " + om.toFixed(2) + " rad/s";

var g = 9.8;
var r = p.radius, m = p.mass, k = p.vtop;
var vtopCrit = Math.sqrt(g * r);
var vtop = k * vtopCrit;

// integrate angle from top
var dt = 0.004;
var steps = Math.floor((t % 8) / dt);
if (steps > 2400) steps = 2400;
var phi = 0.0001;
var i, v2;
for (i = 0; i < steps; i++) {
  v2 = vtop * vtop + 2 * g * r * (1 - Math.cos(phi));
  if (v2 < 0) v2 = 0;
  phi += (Math.sqrt(v2) / r) * dt;
}
phi = phi % (2 * Math.PI);

v2 = vtop * vtop + 2 * g * r * (1 - Math.cos(phi));
if (v2 < 0) v2 = 0;
var Tension = m * v2 / r - m * g * Math.cos(phi);
var slack = Tension < 0;

var Ttop = m * vtop * vtop / r - m * g;
var vbot2 = vtop * vtop + 4 * g * r;
var Tbot = m * vbot2 / r + m * g;

var cx = W * 0.36, cy = H * 0.52;
var R = Math.min(W * 0.24, H * 0.36);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;
ctx.strokeStyle = C.rule;
ctx.setLineDash([4, 5]);
ctx.beginPath(); ctx.arc(cx, cy, R, 0, Math.PI * 2); ctx.stroke();
ctx.setLineDash([]);

// phi measured from the top, clockwise
var bx = cx + R * Math.sin(phi), by = cy - R * Math.cos(phi);

ctx.strokeStyle = slack ? C.faint : C.ink;
if (slack) ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(bx, by); ctx.stroke();
ctx.setLineDash([]);

function arrow(x0, y0, x1, y1, col) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
  var th = Math.atan2(y1 - y0, x1 - x0);
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 7 * Math.cos(th - 0.4), y1 - 7 * Math.sin(th - 0.4));
  ctx.lineTo(x1 - 7 * Math.cos(th + 0.4), y1 - 7 * Math.sin(th + 0.4));
  ctx.closePath(); ctx.fill();
  ctx.lineWidth = 1;
}

// weight arrow on the ball
arrow(bx, by, bx, by + R * 0.34, C.figure);
ctx.fillStyle = C.figure;
ctx.fillText("mg", bx + 5, by + R * 0.34 + 2);

// tension arrow, along the string toward the centre
if (!slack) {
  var ux = (cx - bx), uy = (cy - by);
  var L = Math.sqrt(ux * ux + uy * uy); ux /= L; uy /= L;
  var tl = R * 0.22 + R * 0.5 * Math.min(1, Tension / (6 * m * g));
  arrow(bx, by, bx + ux * tl, by + uy * tl, C.accent);
  ctx.fillStyle = C.accent;
  ctx.fillText("T", bx + ux * tl - 14, by + uy * tl - 4);
}

ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(bx, by, 6, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(cx, cy, 3, 0, Math.PI * 2); ctx.fill();
ctx.fillText("top", cx - 10, cy - R - 8);
ctx.fillText("bottom", cx - 20, cy + R + 18);

// tension bar chart: top, current, bottom
var bx0 = W * 0.64, bw = W * 0.08, base = H * 0.82;
var maxT = Math.max(Tbot, 1);
var vals = [Ttop, Tension, Tbot];
var names = ["T top", "T now", "T bot"];
var j;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(bx0 - 8, base); ctx.lineTo(W * 0.98, base); ctx.stroke();
for (j = 0; j < 3; j++) {
  var val = vals[j];
  var h = (H * 0.6) * Math.max(0, val) / maxT;
  ctx.fillStyle = val <= 0 ? C.faint : (j === 1 ? C.accent : C.figure);
  ctx.fillRect(bx0 + j * bw * 1.5, base - h, bw, Math.max(h, 2));
  ctx.fillStyle = C.ink;
  ctx.fillText(names[j], bx0 + j * bw * 1.5 - 2, base + 14);
  ctx.fillText(val > 0 ? val.toFixed(1) : "0", bx0 + j * bw * 1.5 - 2, base - h - 5);
}
ctx.fillStyle = C.ink;
ctx.fillText("string tension (N)", bx0 - 8, H * 0.14);

out.note = "v_top = " + vtop.toFixed(2) + " m/s (critical " + vtopCrit.toFixed(2) + "),  T at top = " + (Ttop > -0.0001 ? Ttop.toFixed(2) + " N" : "string would go slack") + ",  v at bottom = " + Math.sqrt(vbot2).toFixed(2) + " m/s,  T at bottom = " + Tbot.toFixed(2) + " N";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

function arrow(x0, y0, x1, y1, col) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
  var th = Math.atan2(y1 - y0, x1 - x0);
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 8 * Math.cos(th - 0.4), y1 - 8 * Math.sin(th - 0.4));
  ctx.lineTo(x1 - 8 * Math.cos(th + 0.4), y1 - 8 * Math.sin(th + 0.4));
  ctx.closePath(); ctx.fill();
  ctx.lineWidth = 1;
}

var panel = W / 3;
var cy = H * 0.45;
var L = Math.min(panel * 0.26, H * 0.24);
var k;
for (k = 1; k < 3; k++) {
  ctx.strokeStyle = C.faint;
  ctx.beginPath(); ctx.moveTo(panel * k, H * 0.06); ctx.lineTo(panel * k, H * 0.94); ctx.stroke();
}

// panel 1: top of a vertical circle
var c1 = panel * 0.5;
ctx.fillStyle = C.ink;
ctx.fillText("1. Top of the loop", c1 - panel * 0.4, H * 0.14);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(c1, cy, 7, 0, Math.PI * 2); ctx.fill();
arrow(c1, cy, c1, cy + L, C.figure);
arrow(c1 - 14, cy, c1 - 14, cy + L * 0.7, C.accent);
ctx.fillStyle = C.figure; ctx.fillText("mg", c1 + 6, cy + L * 0.55);
ctx.fillStyle = C.accent; ctx.fillText("T", c1 - 30, cy + L * 0.45);
ctx.fillStyle = C.ink;
ctx.fillText("centre is BELOW", c1 - panel * 0.36, cy + L + 26);
ctx.fillText("T + mg = m v^2 / r", c1 - panel * 0.36, cy + L + 42);

// panel 2: bottom of a vertical circle
var c2 = panel * 1.5;
ctx.fillStyle = C.ink;
ctx.fillText("2. Bottom of the loop", c2 - panel * 0.42, H * 0.14);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(c2, cy, 7, 0, Math.PI * 2); ctx.fill();
arrow(c2, cy, c2, cy + L, C.figure);
arrow(c2 - 14, cy, c2 - 14, cy - L, C.accent);
ctx.fillStyle = C.figure; ctx.fillText("mg", c2 + 6, cy + L * 0.6);
ctx.fillStyle = C.accent; ctx.fillText("T", c2 - 30, cy - L * 0.6);
ctx.fillStyle = C.ink;
ctx.fillText("centre is ABOVE", c2 - panel * 0.36, cy + L + 26);
ctx.fillText("T - mg = m v^2 / r", c2 - panel * 0.36, cy + L + 42);

// panel 3: flat curve, seen from behind
var c3 = panel * 2.5;
ctx.fillStyle = C.ink;
ctx.fillText("3. Flat curve, from behind", c3 - panel * 0.46, H * 0.14);
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(c3 - panel * 0.4, cy + L * 0.6); ctx.lineTo(c3 + panel * 0.4, cy + L * 0.6); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillRect(c3 - 14, cy + L * 0.6 - 16, 28, 16);
arrow(c3, cy + L * 0.6 - 8, c3, cy + L * 0.6 - 8 + L * 0.75, C.figure);
arrow(c3 + 18, cy + L * 0.6 - 8, c3 + 18, cy + L * 0.6 - 8 - L * 0.75, C.figure);
arrow(c3, cy + L * 0.6 - 8, c3 - L * 0.8, cy + L * 0.6 - 8, C.accent);
ctx.fillStyle = C.figure;
ctx.fillText("mg", c3 + 4, cy + L * 0.6 - 8 + L * 0.6);
ctx.fillText("N", c3 + 22, cy + L * 0.6 - 8 - L * 0.6);
ctx.fillStyle = C.accent;
ctx.fillText("f_s (inward)", c3 - L * 0.8 - 6, cy + L * 0.6 - 18);
ctx.fillStyle = C.ink;
ctx.fillText("f_s = m v^2 / r", c3 - panel * 0.36, cy + L + 26);
ctx.fillText("f_s <= mu_s m g", c3 - panel * 0.36, cy + L + 42);

ctx.fillStyle = C.faint;
ctx.fillText("No arrow is ever labelled 'centripetal force'. The label names the source; m v^2 / r is the answer it must add up to.", W * 0.03, H * 0.96);
